DROP TEMPORARY TABLE IF EXISTS `area52_dummy_guid_move`;
CREATE TEMPORARY TABLE `area52_dummy_guid_move` (`old_guid` INT UNSIGNED NOT NULL PRIMARY KEY, `new_guid` INT UNSIGNED NOT NULL UNIQUE) ENGINE=InnoDB;
DELETE FROM `area52_dummy_guid_move`;
INSERT INTO `area52_dummy_guid_move` (`old_guid`, `new_guid`) SELECT `guid`, CASE `guid` WHEN 9780122 THEN 15980122 WHEN 9780124 THEN 15980124 WHEN 9780128 THEN 15980128 WHEN 9780131 THEN 15980131 WHEN 9780132 THEN 15980132 END FROM `creature` WHERE `id` = 967254 AND `map` = 0 AND `guid` IN (9780122, 9780124, 9780128, 9780131, 9780132);
START TRANSACTION;
UPDATE `creature_addon` AS `t` JOIN `area52_dummy_guid_move` AS `m` ON `t`.`guid` = `m`.`old_guid` SET `t`.`guid` = `m`.`new_guid`;
