UPDATE `spawn_group` AS `t` JOIN `area52_dummy_guid_move` AS `m` ON `t`.`spawnId` = `m`.`old_guid` SET `t`.`spawnId` = `m`.`new_guid` WHERE `t`.`spawnType` = 0;
UPDATE `linked_respawn` AS `t` JOIN `area52_dummy_guid_move` AS `m` ON `t`.`guid` = `m`.`old_guid` SET `t`.`guid` = `m`.`new_guid` WHERE `t`.`linkType` IN (0, 1);
UPDATE `linked_respawn` AS `t` JOIN `area52_dummy_guid_move` AS `m` ON `t`.`linkedGuid` = `m`.`old_guid` SET `t`.`linkedGuid` = `m`.`new_guid` WHERE `t`.`linkType` IN (0, 3);
UPDATE `creature` AS `t` JOIN `area52_dummy_guid_move` AS `m` ON `t`.`guid` = `m`.`old_guid` SET `t`.`guid` = `m`.`new_guid`;
